parameters.jsCode:
// Das Formular legt die hochgeladene Datei je nach n8n-Version unter
// `Lebenslauf`, `Lebenslauf_0` oder aehnlich ab. Statt einen Namen zu raten, wird
// hier die erste PDF-Datei gesucht und auf den festen Schluessel `lebenslauf`
// umgehaengt — so bleibt der Extraktions-Node stabil, auch wenn sich das
// Formularfeld spaeter aendert.
const raus = [];
for (const eintrag of $input.all()) {
  const bin = eintrag.binary ?? {};
  const schluessel = Object.keys(bin).find((k) => String(bin[k].mimeType || '').includes('pdf')) ?? Object.keys(bin)[0];
  if (!schluessel) continue;

  raus.push({
    json: {
      ...eintrag.json,
      dateiname: bin[schluessel].fileName ?? 'lebenslauf.pdf',
      dateigroesse: bin[schluessel].fileSize ?? null,
      eingang: new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' })
    },
    binary: { lebenslauf: bin[schluessel] }
  });
}
return raus;

// Anforderungskatalog je Stelle — hier pflegt die Personalabteilung, wogegen
// abgeglichen wird. Warum im Workflow und nicht im Prompt: So steht schwarz auf
// weiss, welche Kriterien angelegt wurden, und die Formulierung bleibt
// nachvollziehbar dokumentiert (Transparenzpflicht, Nachweis gegenueber dem
// Betriebsrat).
const STELLENPROFILE = {
  'Elektroniker Betriebstechnik (m/w/d)': {
    muss: [
      'Abgeschlossene Ausbildung als Elektroniker/in fuer Betriebstechnik oder vergleichbar',
      'Kenntnisse in Schaltschrankbau und Fehlersuche',
      'Fuehrerschein Klasse B'
    ],
    kann: [
      'Erfahrung mit SPS-Programmierung (Siemens TIA)',
      'Schaltberechtigung bis 1 kV',
      'Bereitschaft zur Rufbereitschaft'
    ]
  },
  'Buchhaltung Teilzeit (m/w/d)': {
    muss: [
      'Kaufmaennische Ausbildung oder vergleichbare Qualifikation',
      'Sichere Anwendung einer Buchhaltungssoftware (z. B. DATEV, Lexware)',
      'Erfahrung in der Debitoren- und Kreditorenbuchhaltung'
    ],
    kann: [
      'Weiterbildung zum Finanzbuchhalter/in',
      'Erfahrung mit Umsatzsteuervoranmeldung',
      'Englischkenntnisse'
    ]
  },
  'Kaufmaennische Sachbearbeitung (m/w/d)': {
    muss: [
      'Kaufmaennische Ausbildung',
      'Sicherer Umgang mit MS Office',
      'Sehr gute Deutschkenntnisse in Wort und Schrift'
    ],
    kann: [
      'Erfahrung mit ERP-Systemen',
      'Erfahrung in der Auftragsabwicklung',
      'Englischkenntnisse'
    ]
  }
};

const STANDARD = { muss: ['Passende abgeschlossene Ausbildung oder Studium'], kann: ['Berufserfahrung im ausgeschriebenen Bereich'] };

const raus = [];
for (const eintrag of $input.all()) {
  const stamm = $('Lebenslauf-Datei normalisieren').first().json;
  const stelle = stamm['Stelle'] ?? '';
  const profil = STELLENPROFILE[stelle] ?? STANDARD;

  // Ein leerer Text bedeutet meist ein gescanntes PDF ohne Textebene. Das muss
  // sichtbar werden, sonst halluziniert die KI auf einer leeren Grundlage.
  const text = String(eintrag.json.text ?? '').trim();

  raus.push({
    json: {
      bewerber_name: stamm['Name'] ?? '',
      bewerber_mail: stamm['E-Mail'] ?? '',
      bewerber_telefon: stamm['Telefon'] ?? '',
      stelle,
      motivation: stamm['Kurze Motivation'] ?? '',
      verfuegbarkeit_angabe: stamm['Frueheste Verfuegbarkeit'] ?? '',
      dateiname: stamm.dateiname,
      eingang: stamm.eingang,
      anforderungen_muss: profil.muss,
      anforderungen_kann: profil.kann,
      profil_gefunden: Boolean(STELLENPROFILE[stelle]),
      lebenslauf_text: text,
      text_laenge: text.length,
      text_verwertbar: text.length >= 200,
      pruefhinweis: text.length < 200 ? 'Lebenslauf enthaelt kaum Text — vermutlich ein Scan ohne Textebene. Bitte manuell sichten.' : null
    }
  });
}
return raus;

