parameters.jsCode:
// Baut aus der KI-Struktur ein lesbares Dossier fuer die Personalabteilung.
// Zwei bewusste Sicherungen:
// 1) Erfindet das Modell trotz Prompt doch ein Score-, Ranking- oder Empfehlungsfeld,
//    wird es hier entfernt. Was nicht im Dossier steht, kann auch niemand als
//    Auswahlkriterium missverstehen.
// 2) Es wird nur gezaehlt, wie viele Anforderungen BELEGT sind — nicht bewertet.
//    Die Zahl steht als Navigationshilfe im Text, nicht als Note.
const VERBOTENE_FELDER = ['score', 'punktzahl', 'punkte', 'bewertung', 'ranking', 'rang', 'note', 'eignung', 'eignungsgrad', 'match', 'matching', 'match_score', 'empfehlung', 'entscheidung', 'prozent'];

const raus = [];
for (const eintrag of $input.all()) {
  const k = eintrag.json.message?.content ?? eintrag.json;
  const stamm = $('Stellenprofil laden').first().json;

  const sauber = {};
  for (const [feld, wert] of Object.entries(k)) {
    if (VERBOTENE_FELDER.some((v) => feld.toLowerCase().includes(v))) continue;
    sauber[feld] = wert;
  }

  const abgleich = Array.isArray(sauber.anforderungsabgleich) ? sauber.anforderungsabgleich : [];
  const belegt = abgleich.filter((a) => a.einschaetzung === 'im Lebenslauf belegt').length;

  const zeile = (a) => {
    const marke = a.einschaetzung === 'im Lebenslauf belegt' ? '[belegt]' : (a.einschaetzung === 'teilweise belegt' ? '[teilweise]' : '[nicht gefunden]');
    return `${marke} (${a.art === 'muss' ? 'Muss' : 'Kann'}) ${a.anforderung}\n        Beleg: ${a.beleg || 'kein Beleg im Lebenslauf'}`;
  };

  const stationen = (sauber.stationen || []).map((s) => `- ${s.zeitraum || '?'}: ${s.rolle || '?'} bei ${s.arbeitgeber || '?'}`).join('\n');
  const ausbildung = (sauber.ausbildung || []).map((s) => `- ${s.zeitraum || '?'}: ${s.abschluss || '?'} (${s.einrichtung || '?'})`).join('\n');
  const sprachen = (sauber.sprachen || []).map((s) => `${s.sprache}: ${s.niveau}`).join(', ');

  const dossier = [
    `Bewerbung: ${stamm.bewerber_name} — ${stamm.stelle}`,
    `Eingang: ${stamm.eingang} | Datei: ${stamm.dateiname}`,
    `Kontakt: ${stamm.bewerber_mail} / ${stamm.bewerber_telefon || 'keine Telefonnummer angegeben'}`,
    '',
    'WERDEGANG',
    stationen || 'keine Stationen erkannt',
    '',
    'AUSBILDUNG',
    ausbildung || 'keine Angaben erkannt',
    '',
    `FACHKENNTNISSE: ${(sauber.fachkenntnisse || []).join(', ') || 'keine erkannt'}`,
    `ZERTIFIKATE: ${(sauber.zertifikate || []).join(', ') || 'keine erkannt'}`,
    `SPRACHEN: ${sprachen || 'keine Angaben'}`,
    `VERFUEGBARKEIT: ${sauber.verfuegbarkeit || stamm.verfuegbarkeit_angabe || 'keine Angabe'}`,
    '',
    `ANFORDERUNGSABGLEICH (${belegt} von ${abgleich.length} Anforderungen im Lebenslauf belegt — dies ist keine Bewertung)`,
    abgleich.map(zeile).join('\n') || 'kein Abgleich moeglich',
    '',
    'FRAGEN FUERS GESPRAECH',
    (sauber.offene_fragen || []).map((f) => `- ${f}`).join('\n') || 'keine',
    '',
    'SACHLICHE BEOBACHTUNGEN',
    (sauber.auffaelligkeiten || []).map((f) => `- ${f}`).join('\n') || 'keine',
    stamm.pruefhinweis ? `\nACHTUNG: ${stamm.pruefhinweis}` : '',
    stamm.profil_gefunden ? '' : '\nACHTUNG: Fuer diese Stelle ist kein Anforderungsprofil hinterlegt — es wurde gegen ein allgemeines Standardprofil abgeglichen.'
  ].join('\n');

  raus.push({
    json: {
      ...stamm,
      lebenslauf_text: undefined, // Rohtext nicht weiterschleppen — Datenminimierung
      struktur: sauber,
      anforderungen_gesamt: abgleich.length,
      anforderungen_belegt: belegt,
      dossier_text: dossier,
      automatische_entscheidung: false,
      hinweis_ai_act: 'Diese Zusammenfassung ist KI-gestuetzt und dient ausschliesslich der Vorbereitung. Es wurde weder bewertet noch vorsortiert noch abgelehnt. Die Auswahlentscheidung trifft die Personalabteilung.'
    }
  });
}
return raus;

